import crypto from 'node:crypto'
import fs from 'node:fs'
import path from 'node:path'
import process from 'node:process'
import { fileURLToPath } from 'node:url'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const sourcePath = path.join(root, 'spec/tokens/tokens.json')
const generatedHeader =
  'Generated by scripts/token-pipeline.mjs. Do not edit manually.'

const outputPaths = {
  css: 'vue/packages/theme-chalk/src/generated/tokens.css',
  scss: 'vue/packages/theme-chalk/src/generated/tokens.scss',
  json: 'vue/packages/theme-chalk/src/generated/tokens.json',
  avaloniaXaml: 'dotnet/FsusUI.Avalonia.Themes/Generated/FsusTokens.axaml',
  csharp: 'dotnet/FsusUI.Avalonia/Generated/FsusTokens.g.cs',
  docs: 'docs/theme/generated/tokens.md',
  hash: 'generated/tokens.hash.json',
}

const allowedCategories = new Set([
  'primitive',
  'color',
  'brush',
  'typography',
  'space',
  'thickness',
  'radius',
  'border',
  'shadow',
  'opacity',
  'z',
  'motion',
  'density',
  'icon',
  'component',
  'component-state',
])

const allowedTypes = new Set([
  'color',
  'brush',
  'dimension',
  'duration',
  'easing',
  'fontFamily',
  'fontWeight',
  'number',
  'opacity',
  'radius',
  'shadow',
  'string',
  'thickness',
  'zIndex',
])

const requiredPlatforms = ['web', 'avalonia']
const requiredTokenLayers = [
  'primitive',
  'semantic',
  'component',
  'component-state',
]
const requiredDimensions = {
  theme: ['light', 'dark'],
  density: ['compact', 'default', 'spacious'],
  motion: ['full', 'reduced', 'disabled'],
}
const namePattern = /^[a-z][a-z0-9]*(?:[.-][a-z0-9]+)*$/
const referencePattern = /\{([^}]+)\}/g
const tokenSnapshotPath = path.join(
  root,
  'tests/fixtures/token-v2/output-snapshots.json',
)
const avaloniaTypeSnapshotPath = path.join(
  root,
  'tests/fixtures/token-v2/avalonia-type-snapshots.json',
)

const toPosix = (filePath) => filePath.split(path.sep).join('/')

const rel = (filePath) => toPosix(path.relative(root, filePath))

const sha256 = (content) =>
  crypto.createHash('sha256').update(content).digest('hex')

const readSource = () => {
  const source = JSON.parse(fs.readFileSync(sourcePath, 'utf8'))
  validateSource(source)
  return source
}

const getTokenMap = (tokens) =>
  new Map(tokens.map((token) => [token.name, token]))

const validateSource = (source) => {
  if (source.version !== 2) {
    throw new Error('spec/tokens/tokens.json must declare version 2')
  }
  if (!Array.isArray(source.tokens) || source.tokens.length === 0) {
    throw new Error(
      'spec/tokens/tokens.json must contain a non-empty tokens array',
    )
  }
  validateTokenV2Metadata(source)

  const names = new Set()
  const semanticMeanings = new Map()
  for (const token of source.tokens) {
    validateToken(source, token, names)
    const semanticMeaning = token.semanticMeaning
    if (semanticMeaning) {
      if (semanticMeanings.has(semanticMeaning)) {
        throw new Error(
          `${token.name} duplicates semantic meaning ${semanticMeaning} from ${semanticMeanings.get(
            semanticMeaning,
          )}`,
        )
      }
      semanticMeanings.set(semanticMeaning, token.name)
    }
    names.add(token.name)
  }

  for (const token of source.tokens) {
    for (const reference of findTokenReferences(token)) {
      if (!names.has(reference)) {
        throw new Error(`${token.name} references missing token ${reference}`)
      }
    }
  }

  const tokenMap = getTokenMap(source.tokens)
  const usedLayers = new Set()
  for (const token of source.tokens) {
    usedLayers.add(layerForToken(source, token))
    const resolved = resolveValue(token, tokenMap)
    validateResolvedTokenValue(token, resolved)
    for (const [modeName, modeValue] of Object.entries(
      token.modeValues ?? {},
    )) {
      validateModeValue(token, modeName, modeValue)
      validateResolvedTokenValue(
        token,
        resolveValue(token, tokenMap, new Set(), modeName),
      )
    }
  }

  for (const layer of requiredTokenLayers) {
    if (!usedLayers.has(layer)) {
      throw new Error(`Token v2 layer ${layer} has no registered tokens`)
    }
  }
}

const validateTokenV2Metadata = (source) => {
  for (const layer of requiredTokenLayers) {
    if (
      !Array.isArray(source.layers?.[layer]) ||
      source.layers[layer].length === 0
    ) {
      throw new Error(`Token v2 layer ${layer} must declare match patterns`)
    }
  }
  for (const [dimension, values] of Object.entries(requiredDimensions)) {
    for (const value of values) {
      if (!source.dimensions?.[dimension]?.includes(value)) {
        throw new Error(`Token v2 dimension ${dimension} must include ${value}`)
      }
    }
  }
}

const validateToken = (source, token, names) => {
  for (const field of ['name', 'type', 'value', 'description', 'platforms']) {
    if (token[field] === undefined || token[field] === '') {
      throw new Error(`Token is missing required field ${field}`)
    }
  }

  if (names.has(token.name)) {
    throw new Error(`Duplicate token name ${token.name}`)
  }

  if (!namePattern.test(token.name)) {
    throw new Error(`Invalid token name ${token.name}`)
  }

  const category = token.name.split('.')[0]
  if (!allowedCategories.has(category)) {
    throw new Error(`Unsupported token category ${category} in ${token.name}`)
  }

  if (!allowedTypes.has(token.type)) {
    throw new Error(`Unsupported token type ${token.type} in ${token.name}`)
  }

  layerForToken(source, token)

  if (!Array.isArray(token.platforms)) {
    throw new Error(`${token.name} platforms must be an array`)
  }

  for (const platform of requiredPlatforms) {
    if (!token.platforms.includes(platform)) {
      throw new Error(`${token.name} must support ${platform}`)
    }
  }

  if (token.aliases !== undefined) {
    if (!Array.isArray(token.aliases)) {
      throw new Error(`${token.name} aliases must be an array`)
    }
    for (const alias of token.aliases) {
      if (!alias.startsWith('--')) {
        throw new Error(`${token.name} alias ${alias} must be a CSS variable`)
      }
    }
  }
}

const layerForToken = (source, token) => {
  for (const [layer, patterns] of Object.entries(source.layers ?? {})) {
    for (const pattern of patterns) {
      if (
        pattern.endsWith('*') &&
        token.name.startsWith(pattern.slice(0, -1))
      ) {
        return layer
      }
      if (token.name === pattern) return layer
    }
  }
  throw new Error(`${token.name} is not assigned to a Token v2 layer`)
}

const validateModeValue = (token, modeName, modeValue) => {
  if (!modeValue || typeof modeValue !== 'object') {
    throw new Error(
      `${token.name} mode ${modeName} must declare value and fallback`,
    )
  }
  if (modeValue.value === undefined || modeValue.fallback === undefined) {
    throw new Error(`${token.name} mode ${modeName} is missing fallback token`)
  }
}

const validateResolvedTokenValue = (token, value) => {
  const raw = String(value)
  const type = token.type
  const fail = () => {
    throw new Error(`${token.name} has invalid ${type} value ${raw}`)
  }

  if (type === 'color' && !/^#(?:[0-9A-Fa-f]{6}|[0-9A-Fa-f]{8})$/.test(raw))
    fail()
  if (type === 'brush' && !/^#(?:[0-9A-Fa-f]{6}|[0-9A-Fa-f]{8})$/.test(raw))
    fail()
  if (
    ['dimension', 'radius', 'thickness'].includes(type) &&
    !/^-?\d+(?:\.\d+)?(?:px|rem)$/.test(raw)
  ) {
    fail()
  }
  if (type === 'duration' && !/^\d+(?:\.\d+)?ms$/.test(raw)) fail()
  if (type === 'easing' && !/^(?:linear|cubic-bezier\([^)]+\))$/.test(raw))
    fail()
  if (type === 'fontFamily' && raw.length < 2) fail()
  if (type === 'fontWeight' && !/^\d{3}$/.test(raw)) fail()
  if (type === 'opacity') {
    const valueNumber = Number(raw)
    if (!Number.isFinite(valueNumber) || valueNumber < 0 || valueNumber > 1)
      fail()
  }
  if (type === 'zIndex' && !/^\d+$/.test(raw)) fail()
  if (type === 'number' && Number.isNaN(Number(raw))) fail()
}

const findTokenReferences = (token) => [
  ...findReferences(token.value),
  ...Object.values(token.modeValues ?? {}).flatMap((modeValue) => [
    ...findReferences(modeValue.value),
    ...(modeValue.fallback ? [modeValue.fallback] : []),
  ]),
]

const findReferences = (value) => {
  const references = []
  const raw = String(value)
  for (const match of raw.matchAll(referencePattern)) {
    references.push(match[1])
  }
  return references
}

const resolveValue = (token, tokenMap, seen = new Set(), modeName) => {
  if (seen.has(token.name)) {
    throw new Error(`Circular token reference involving ${token.name}`)
  }

  seen.add(token.name)
  const raw = String(token.modeValues?.[modeName]?.value ?? token.value)
  return raw.replace(referencePattern, (_, name) => {
    const referenced = tokenMap.get(name)
    if (!referenced) {
      throw new Error(`${token.name} references missing token ${name}`)
    }
    return resolveValue(referenced, tokenMap, new Set(seen), modeName)
  })
}

const cssName = (name) => `--fsus-${name.replace(/[.]/g, '-')}`

const pascalName = (name) =>
  `Fsus${name
    .split(/[.-]/g)
    .map((part) => `${part.charAt(0).toUpperCase()}${part.slice(1)}`)
    .join('')}`

const csharpName = (name) =>
  name
    .split(/[.-]/g)
    .map((part) => `${part.charAt(0).toUpperCase()}${part.slice(1)}`)
    .join('')

const modeSuffix = (modeName) =>
  modeName.replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase()

const stripUnit = (value) => String(value).replace(/px$/, '').replace(/ms$/, '')

const xmlEscape = (value) =>
  String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')

const cssEscape = (value) => String(value).replaceAll('\n', ' ')

const scssMapValue = (token, tokenMap) => {
  const value = resolveValue(token, tokenMap)
  if (token.type === 'fontFamily') return `(${value})`
  return value
}

const csharpEscape = (value) =>
  String(value).replaceAll('\\', '\\\\').replaceAll('"', '\\"')

const numericValue = (value) => {
  const number = Number(stripUnit(value))
  if (!Number.isFinite(number)) {
    throw new Error(`Cannot convert ${value} to an Avalonia numeric value`)
  }
  return String(number)
}

const csharpDoubleLiteral = (value) => `${numericValue(value)}d`

const timeSpanText = (value) => {
  const milliseconds = Number(String(value).replace(/ms$/, ''))
  if (!Number.isFinite(milliseconds)) {
    throw new Error(`Cannot convert ${value} to an Avalonia TimeSpan`)
  }
  const ticks = Math.round(milliseconds * 10_000)
  const ticksPerSecond = 10_000_000
  const ticksPerMinute = ticksPerSecond * 60
  const ticksPerHour = ticksPerMinute * 60
  const hours = Math.floor(ticks / ticksPerHour)
  const minutes = Math.floor((ticks % ticksPerHour) / ticksPerMinute)
  const seconds = Math.floor((ticks % ticksPerMinute) / ticksPerSecond)
  const fraction = ticks % ticksPerSecond
  const pad2 = (part) => String(part).padStart(2, '0')
  return `${pad2(hours)}:${pad2(minutes)}:${pad2(seconds)}.${String(fraction).padStart(7, '0')}`
}

const parseEasing = (value) => {
  const raw = String(value).trim()
  if (raw === 'linear') return { type: 'linear' }
  const match = /^cubic-bezier\(([^,]+),([^,]+),([^,]+),([^)]+)\)$/.exec(raw)
  if (!match) {
    throw new Error(`Unsupported Avalonia easing value ${value}`)
  }
  const points = match.slice(1).map((part) => {
    const number = Number(part.trim())
    if (!Number.isFinite(number)) {
      throw new Error(`Unsupported Avalonia easing value ${value}`)
    }
    return String(number)
  })
  return {
    type: 'spline',
    x1: points[0],
    y1: points[1],
    x2: points[2],
    y2: points[3],
  }
}

const avaloniaResourceKindForToken = (token) => {
  const category = token.name.split('.')[0]
  const lowerName = token.name.toLowerCase()

  if (token.type === 'color') return 'color'
  if (token.type === 'brush') return 'brush'
  if (token.type === 'duration') return 'timeSpan'
  if (token.type === 'easing') return 'easing'
  if (token.type === 'fontFamily') return 'fontFamily'
  if (token.type === 'fontWeight') return 'fontWeight'
  if (token.type === 'shadow') return 'boxShadows'
  if (token.type === 'zIndex') return 'int'
  if (token.type === 'radius' || lowerName.includes('radius'))
    return 'cornerRadius'
  if (
    token.type === 'thickness' ||
    category === 'space' ||
    category === 'border' ||
    lowerName.includes('padding') ||
    lowerName.includes('margin')
  ) {
    return 'thickness'
  }
  if (
    token.type === 'dimension' ||
    token.type === 'number' ||
    token.type === 'opacity'
  ) {
    return 'double'
  }
  return 'string'
}

const renderCss = (source, tokenMap) => {
  const lines = [
    `/* ${generatedHeader} */`,
    ':root, [data-fsus-theme="light"] {',
  ]
  for (const token of source.tokens) {
    const value = cssEscape(resolveValue(token, tokenMap))
    lines.push(`  ${cssName(token.name)}: ${value};`)
    for (const alias of token.aliases ?? []) {
      lines.push(`  ${alias}: var(${cssName(token.name)});`)
    }
  }
  lines.push('}', '')
  const modeSelectors = {
    dark: '[data-fsus-theme="dark"]',
    densityCompact: '[data-fsus-density="compact"]',
    densitySpacious: '[data-fsus-density="spacious"]',
    motionReduced: '[data-fsus-motion="reduced"]',
    motionDisabled: '[data-fsus-motion="disabled"]',
  }
  for (const [modeName, selector] of Object.entries(modeSelectors)) {
    const modeTokens = source.tokens.filter(
      (token) => token.modeValues?.[modeName],
    )
    if (modeTokens.length === 0) continue
    lines.push(`${selector} {`)
    for (const token of modeTokens) {
      lines.push(
        `  ${cssName(token.name)}: ${cssEscape(resolveValue(token, tokenMap, new Set(), modeName))};`,
      )
    }
    lines.push('}', '')
  }
  return lines.join('\n')
}

const renderScss = (source, tokenMap) => {
  const lines = [`// ${generatedHeader}`]
  for (const token of source.tokens) {
    lines.push(
      `$fsus-${token.name.replace(/[.]/g, '-')}: ${resolveValue(token, tokenMap)};`,
    )
    for (const modeName of Object.keys(token.modeValues ?? {})) {
      lines.push(
        `$fsus-${token.name.replace(/[.]/g, '-')}-${modeSuffix(modeName)}: ${resolveValue(token, tokenMap, new Set(), modeName)};`,
      )
    }
  }

  lines.push('', '$fsus-tokens: (')
  for (const token of source.tokens) {
    lines.push(`  '${token.name}': ${scssMapValue(token, tokenMap)},`)
  }
  lines.push(');', '', '$fsus-token-aliases: (')
  for (const token of source.tokens) {
    for (const alias of token.aliases ?? []) {
      lines.push(`  '${alias}': '${cssName(token.name)}',`)
    }
  }
  lines.push(');', '')
  return lines.join('\n')
}

const renderJson = (source, tokenMap) => {
  const tokens = Object.fromEntries(
    source.tokens.map((token) => [
      token.name,
      {
        type: token.type,
        value: resolveValue(token, tokenMap),
        layer: layerForToken(source, token),
        css: cssName(token.name),
        avalonia: pascalName(token.name),
        description: token.description,
        aliases: token.aliases ?? [],
        modeValues: Object.fromEntries(
          Object.entries(token.modeValues ?? {}).map(([modeName]) => [
            modeName,
            resolveValue(token, tokenMap, new Set(), modeName),
          ]),
        ),
      },
    ]),
  )

  return `${JSON.stringify(
    {
      generatedBy: 'scripts/token-pipeline.mjs',
      note: generatedHeader,
      version: source.version,
      layers: source.layers,
      dimensions: source.dimensions,
      tokens,
    },
    null,
    2,
  )}\n`
}

const renderAvaloniaXaml = (source, tokenMap) => {
  const lines = [
    '<ResourceDictionary',
    '  xmlns="https://github.com/avaloniaui"',
    '  xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml">',
    `  <!-- ${generatedHeader} -->`,
  ]

  for (const token of source.tokens) {
    const key = pascalName(token.name)
    const value = xmlEscape(resolveValue(token, tokenMap))
    const kind = avaloniaResourceKindForToken(token)

    if (kind === 'color') {
      lines.push(`  <Color x:Key="${key}">${value}</Color>`)
      lines.push(`  <SolidColorBrush x:Key="${key}Brush" Color="${value}" />`)
      for (const modeName of Object.keys(token.modeValues ?? {})) {
        const modeKey = `${key}${csharpName(modeName)}`
        const modeValue = xmlEscape(
          resolveValue(token, tokenMap, new Set(), modeName),
        )
        lines.push(`  <Color x:Key="${modeKey}">${modeValue}</Color>`)
        lines.push(
          `  <SolidColorBrush x:Key="${modeKey}Brush" Color="${modeValue}" />`,
        )
      }
      continue
    }

    if (kind === 'brush') {
      lines.push(`  <SolidColorBrush x:Key="${key}" Color="${value}" />`)
      continue
    }

    if (kind === 'cornerRadius') {
      lines.push(
        `  <CornerRadius x:Key="${key}">${stripUnit(value)}</CornerRadius>`,
      )
      continue
    }

    if (kind === 'thickness') {
      lines.push(`  <Thickness x:Key="${key}">${stripUnit(value)}</Thickness>`)
      continue
    }

    if (kind === 'fontFamily') {
      lines.push(`  <FontFamily x:Key="${key}">${value}</FontFamily>`)
      continue
    }

    if (kind === 'fontWeight') {
      lines.push(
        `  <FontWeight x:Key="${key}">${numericValue(value)}</FontWeight>`,
      )
      continue
    }

    if (kind === 'timeSpan') {
      lines.push(
        `  <x:TimeSpan x:Key="${key}">${timeSpanText(value)}</x:TimeSpan>`,
      )
      continue
    }

    if (kind === 'easing') {
      const easing = parseEasing(value)
      if (easing.type === 'linear') {
        lines.push(`  <LinearEasing x:Key="${key}" />`)
      } else {
        lines.push(
          `  <SplineEasing x:Key="${key}" X1="${easing.x1}" Y1="${easing.y1}" X2="${easing.x2}" Y2="${easing.y2}" />`,
        )
      }
      continue
    }

    if (kind === 'boxShadows') {
      lines.push(`  <BoxShadows x:Key="${key}">${value}</BoxShadows>`)
      continue
    }

    if (kind === 'double') {
      lines.push(`  <x:Double x:Key="${key}">${stripUnit(value)}</x:Double>`)
      continue
    }

    if (kind === 'int') {
      lines.push(`  <x:Int32 x:Key="${key}">${numericValue(value)}</x:Int32>`)
      continue
    }

    lines.push(`  <x:String x:Key="${key}">${value}</x:String>`)
  }

  lines.push('</ResourceDictionary>', '')
  return lines.join('\n')
}

const renderCsharpAccessorLines = (token, tokenMap) => {
  const name = csharpName(token.name)
  const value = resolveValue(token, tokenMap)
  const kind = avaloniaResourceKindForToken(token)
  const escapedValue = csharpEscape(value)

  if (kind === 'color') {
    return [
      `    public const string ${name}BrushResourceKey = "${pascalName(token.name)}Brush";`,
      `    public static Color ${name}Color => Color.Parse(${name}Value);`,
      `    public static SolidColorBrush ${name}Brush => new(${name}Color);`,
    ]
  }

  if (kind === 'brush') {
    return [
      `    public static SolidColorBrush ${name}Brush => new(Color.Parse(${name}Value));`,
    ]
  }

  if (kind === 'thickness') {
    return [
      `    public static Thickness ${name}Thickness => new(${csharpDoubleLiteral(value)});`,
    ]
  }

  if (kind === 'cornerRadius') {
    return [
      `    public static CornerRadius ${name}CornerRadius => new(${csharpDoubleLiteral(value)});`,
    ]
  }

  if (kind === 'fontFamily') {
    return [
      `    public static FontFamily ${name}FontFamily => FontFamily.Parse(${name}Value);`,
    ]
  }

  if (kind === 'fontWeight') {
    return [
      `    public static FontWeight ${name}FontWeight => (FontWeight)${numericValue(value)};`,
    ]
  }

  if (kind === 'timeSpan') {
    return [
      `    public static TimeSpan ${name}TimeSpan => TimeSpan.FromMilliseconds(${csharpDoubleLiteral(value)});`,
    ]
  }

  if (kind === 'easing') {
    const easing = parseEasing(value)
    if (easing.type === 'linear') {
      return [`    public static IEasing ${name}Easing => new LinearEasing();`]
    }
    return [
      `    public static IEasing ${name}Easing => new SplineEasing { X1 = ${easing.x1}d, Y1 = ${easing.y1}d, X2 = ${easing.x2}d, Y2 = ${easing.y2}d };`,
    ]
  }

  if (kind === 'boxShadows') {
    if (String(value).trim() === 'none') {
      return [`    public static BoxShadows ${name}BoxShadows => default;`]
    }
    return [
      `    public static BoxShadows ${name}BoxShadows => BoxShadows.Parse("${escapedValue}");`,
    ]
  }

  if (kind === 'double') {
    return [
      `    public static double ${name}Double => ${csharpDoubleLiteral(value)};`,
    ]
  }

  if (kind === 'int') {
    return [`    public static int ${name}Int32 => ${numericValue(value)};`]
  }

  return []
}

const renderCsharp = (source, tokenMap) => {
  const lines = [
    '// <auto-generated />',
    `// ${generatedHeader}`,
    'using System;',
    'using Avalonia;',
    'using Avalonia.Animation.Easings;',
    'using Avalonia.Controls;',
    'using Avalonia.Media;',
    '',
    'namespace FsusUI.Avalonia;',
    '',
    'public static class FsusTokens',
    '{',
    '    public static T GetResource<T>(IResourceHost host, string resourceKey)',
    '    {',
    '        ArgumentNullException.ThrowIfNull(host);',
    '        ArgumentException.ThrowIfNullOrWhiteSpace(resourceKey);',
    '',
    '        if (host.TryGetResource(resourceKey, out var resource) && resource is T typed)',
    '            return typed;',
    '',
    '        var actualType = resource?.GetType().FullName ?? "missing";',
    '        throw new InvalidOperationException(',
    '            $"Resource \'{resourceKey}\' was {actualType}, expected {typeof(T).FullName}.");',
    '    }',
    '',
  ]

  for (const token of source.tokens) {
    const name = csharpName(token.name)
    const resourceKey = pascalName(token.name)
    const value = csharpEscape(resolveValue(token, tokenMap))
    lines.push(`    public const string ${name}Name = "${token.name}";`)
    lines.push(`    public const string ${name}ResourceKey = "${resourceKey}";`)
    lines.push(`    public const string ${name}Value = "${value}";`)
    for (const modeName of Object.keys(token.modeValues ?? {})) {
      const suffix = csharpName(modeName)
      const modeValue = csharpEscape(
        resolveValue(token, tokenMap, new Set(), modeName),
      )
      lines.push(
        `    public const string ${name}${suffix}ResourceKey = "${resourceKey}${suffix}";`,
      )
      lines.push(
        `    public const string ${name}${suffix}Value = "${modeValue}";`,
      )
    }
    lines.push(...renderCsharpAccessorLines(token, tokenMap))
    lines.push('')
  }

  lines.push('}', '')
  return lines.join('\n')
}

const renderMarkdownTable = (headers, rows) => {
  const widths = headers.map((header, index) =>
    Math.max(header.length, 3, ...rows.map((row) => String(row[index]).length)),
  )
  const formatRow = (row) =>
    `| ${row.map((cell, index) => String(cell).padEnd(widths[index])).join(' | ')} |`

  return [
    formatRow(headers),
    formatRow(widths.map((width) => '-'.repeat(width))),
    ...rows.map(formatRow),
  ].join('\n')
}

const renderDocs = (source, tokenMap) => {
  const lines = ['# Generated Tokens', '', `<!-- ${generatedHeader} -->`, '']

  lines.push(
    renderMarkdownTable(
      [
        'Token',
        'Layer',
        'Type',
        'CSS Variable',
        'Avalonia Resource',
        'Value',
        'Mode Values',
      ],
      source.tokens.map((token) => [
        `\`${token.name}\``,
        layerForToken(source, token),
        token.type,
        `\`${cssName(token.name)}\``,
        `\`${pascalName(token.name)}\``,
        `\`${resolveValue(token, tokenMap)}\``,
        Object.keys(token.modeValues ?? {}).length === 0
          ? '—'
          : Object.keys(token.modeValues)
              .map(
                (modeName) =>
                  `\`${modeName}: ${resolveValue(token, tokenMap, new Set(), modeName)}\``,
              )
              .join('<br>'),
      ]),
    ),
  )

  lines.push(
    '',
    'Compatibility aliases are emitted only when they point back to platform-neutral source tokens.',
    '',
  )
  return lines.join('\n')
}

const renderAll = () => {
  const source = readSource()
  const tokenMap = getTokenMap(source.tokens)
  const files = {
    [outputPaths.css]: renderCss(source, tokenMap),
    [outputPaths.scss]: renderScss(source, tokenMap),
    [outputPaths.json]: renderJson(source, tokenMap),
    [outputPaths.avaloniaXaml]: renderAvaloniaXaml(source, tokenMap),
    [outputPaths.csharp]: renderCsharp(source, tokenMap),
    [outputPaths.docs]: renderDocs(source, tokenMap),
  }

  const sourceHash = sha256(fs.readFileSync(sourcePath, 'utf8'))
  files[outputPaths.hash] = `${JSON.stringify(
    {
      generatedBy: 'scripts/token-pipeline.mjs',
      note: generatedHeader,
      source: 'spec/tokens/tokens.json',
      sourceHash,
      outputs: Object.fromEntries(
        Object.entries(files).map(([filePath, content]) => [
          filePath,
          sha256(content),
        ]),
      ),
    },
    null,
    2,
  )}\n`

  return files
}

const writeFiles = (files) => {
  for (const [relativePath, content] of Object.entries(files)) {
    const absolutePath = path.join(root, relativePath)
    fs.mkdirSync(path.dirname(absolutePath), { recursive: true })
    fs.writeFileSync(absolutePath, content)
    console.log(`wrote ${relativePath}`)
  }
}

const checkFiles = (files) => {
  const failures = []
  for (const [relativePath, expected] of Object.entries(files)) {
    const absolutePath = path.join(root, relativePath)
    if (!fs.existsSync(absolutePath)) {
      failures.push(`${relativePath} is missing`)
      continue
    }
    const actual = fs.readFileSync(absolutePath, 'utf8')
    if (actual !== expected) {
      failures.push(`${relativePath} is stale`)
    }
  }

  if (failures.length > 0) {
    throw new Error(`Token artifacts are not current:\n${failures.join('\n')}`)
  }

  console.log('Token artifacts are current.')
}

const lintGeneratedHeaders = () => {
  const generatedFiles = Object.values(outputPaths).map((relativePath) =>
    path.join(root, relativePath),
  )

  for (const filePath of generatedFiles) {
    if (!fs.existsSync(filePath)) continue
    const content = fs.readFileSync(filePath, 'utf8')
    if (!content.includes(generatedHeader)) {
      throw new Error(`${rel(filePath)} is missing the generated file header`)
    }
  }
}

const lintRegisteredAliases = (source) => {
  const aliases = new Set()
  for (const token of source.tokens) {
    for (const alias of token.aliases ?? []) {
      if (aliases.has(alias)) {
        throw new Error(`Duplicate token alias ${alias}`)
      }
      aliases.add(alias)
    }
  }
}

const lintTokenFixtures = () => {
  const fixturePath = path.join(
    root,
    'tests/fixtures/token-v2/schema-cases.json',
  )
  const fixture = JSON.parse(fs.readFileSync(fixturePath, 'utf8'))
  validateSource(fixture.valid)
  for (const testCase of fixture.invalid) {
    const source = JSON.parse(JSON.stringify(fixture.valid))
    for (const mutation of testCase.mutations ?? []) {
      if (mutation.path === 'remove-platform') {
        const token = source.tokens.find((item) => item.name === mutation.token)
        token.platforms = token.platforms.filter(
          (platform) => platform !== mutation.platform,
        )
        continue
      }
      if (mutation.path === 'push-token') {
        source.tokens.push(mutation.token)
        continue
      }
      const token = source.tokens.find((item) => item.name === mutation.token)
      if (!token)
        throw new Error(`Unknown token fixture mutation ${mutation.token}`)
      if (mutation.path === 'value') token.value = mutation.value
      if (mutation.path === 'modeValues') token.modeValues = mutation.value
      if (mutation.path === 'semanticMeaning') {
        token.semanticMeaning = mutation.value
      }
    }
    let failed = false
    try {
      validateSource(source)
    } catch (error) {
      failed = String(error instanceof Error ? error.message : error).includes(
        testCase.errorIncludes,
      )
    }
    if (!failed) {
      throw new Error(
        `Token v2 invalid fixture did not fail as expected: ${testCase.name}`,
      )
    }
  }
}

const lintOutputSnapshots = () => {
  const files = renderAll()
  const snapshot = JSON.parse(fs.readFileSync(tokenSnapshotPath, 'utf8'))
  for (const [key, relativePath] of Object.entries({
    webCss: outputPaths.css,
    webScss: outputPaths.scss,
    json: outputPaths.json,
    avaloniaXaml: outputPaths.avaloniaXaml,
    csharp: outputPaths.csharp,
  })) {
    const actualHash = sha256(files[relativePath])
    if (snapshot[key] !== actualHash) {
      throw new Error(`Token output snapshot ${key} is stale`)
    }
  }
}

const lintAvaloniaTypeSnapshots = (source) => {
  const snapshots = JSON.parse(
    fs.readFileSync(avaloniaTypeSnapshotPath, 'utf8'),
  )
  const tokenMap = getTokenMap(source.tokens)
  const files = renderAll()
  const generatedXaml = files[outputPaths.avaloniaXaml]
  const generatedCsharp = files[outputPaths.csharp]
  const sourceTokens = new Map(
    source.tokens.map((token) => [token.name, token]),
  )
  const failures = []

  if (!generatedCsharp.includes('public static T GetResource<T>(')) {
    failures.push('C# output is missing the typed GetResource<T> helper')
  }

  for (const [snapshotName, snapshot] of Object.entries(snapshots)) {
    const token = sourceTokens.get(snapshot.token)
    if (!token) {
      failures.push(
        `${snapshotName} references missing token ${snapshot.token}`,
      )
      continue
    }

    const actualKind = avaloniaResourceKindForToken(token)
    if (actualKind !== snapshot.kind) {
      failures.push(
        `${snapshot.token} expected Avalonia kind ${snapshot.kind} but resolved ${actualKind}`,
      )
    }

    for (const expected of snapshot.xaml ?? []) {
      if (!generatedXaml.includes(expected)) {
        failures.push(`${snapshot.token} XAML snapshot is missing ${expected}`)
      }
    }
    for (const expected of snapshot.csharp ?? []) {
      if (!generatedCsharp.includes(expected)) {
        failures.push(`${snapshot.token} C# snapshot is missing ${expected}`)
      }
    }

    const key = pascalName(token.name)
    if (
      actualKind !== 'string' &&
      generatedXaml.includes(`<x:String x:Key="${key}"`)
    ) {
      failures.push(`${snapshot.token} still emits a string-only XAML resource`)
    }

    resolveValue(token, tokenMap)
  }

  if (failures.length) {
    throw new Error(
      `Avalonia typed token snapshots failed:\n${failures.join('\n')}`,
    )
  }
}

const lintStableComponentHardcoding = () => {
  const scanRoots = [
    'dotnet/FsusUI.Avalonia/Controls',
    'dotnet/FsusUI.Avalonia.Themes/Themes/Controls',
  ]
  const banned = [
    /#[0-9A-Fa-f]{6,8}/,
    /\b(?:Padding|Margin|MinWidth|MinHeight|CornerRadius)="\d+(?:\.\d+)?"/,
    /\b(?:Duration|Delay)="\d+(?:\.\d+)?ms"/,
  ]
  const failures = []
  const walk = (directory) => {
    if (!fs.existsSync(directory)) return
    for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
      const fullPath = path.join(directory, entry.name)
      if (entry.isDirectory()) {
        walk(fullPath)
        continue
      }
      if (!/\.(axaml|cs)$/.test(entry.name)) continue
      const content = fs.readFileSync(fullPath, 'utf8')
      for (const pattern of banned) {
        if (pattern.test(content))
          failures.push(`${rel(fullPath)} contains ${pattern}`)
      }
    }
  }
  for (const scanRoot of scanRoots) walk(path.join(root, scanRoot))
  if (failures.length) {
    throw new Error(
      `Stable component token hardcoding detected:\n${failures.join('\n')}`,
    )
  }
}

const allowedWebRadiusFallbacks = new Set([
  '4px',
  '6px',
  '10px',
  '12px',
  '24px',
  '999px',
])

const stripStyleComments = (content) =>
  content
    .replace(/\/\*[\s\S]*?\*\//gu, (comment) => comment.replace(/[^\n]/gu, ' '))
    .replace(/^[\t ]*\/\/.*$/gmu, (comment) => ' '.repeat(comment.length))

export const findWebRadiusScaleViolations = (content, file = '<source>') => {
  const source = stripStyleComments(content)
  const literalValuePattern = /^-?(?:\d+(?:\.\d+)?|\.\d+)(?:[a-z]+|%)?$/i
  const failures = []
  const fallbackPattern = /var\(\s*(--fsus-radius-[\w-]+)\s*,\s*([^,)]+)\)/gu

  for (const match of source.matchAll(fallbackPattern)) {
    const fallback = match[2].trim()
    if (
      literalValuePattern.test(fallback) &&
      !allowedWebRadiusFallbacks.has(fallback)
    ) {
      const line = source.slice(0, match.index).split('\n').length
      failures.push(
        `${file}:${line} ${match[1]} uses off-scale fallback ${fallback}`,
      )
    }
  }

  const obsoleteBareRadiusPattern =
    /(?:^|[;{\n])[\t ]*border-radius\s*:\s*(8px)\s*(?:!important\s*)?;/gmu
  for (const match of source.matchAll(obsoleteBareRadiusPattern)) {
    const declarationIndex = match.index + match[0].indexOf('border-radius')
    const line = source.slice(0, declarationIndex).split('\n').length
    failures.push(
      `${file}:${line} uses obsolete bare radius ${match[1]}; use a canonical --fsus-radius-* token`,
    )
  }

  return failures
}

const lintWebRadiusUsage = () => {
  const scanRoot = path.join(root, 'vue/packages/theme-chalk/src')
  const failures = []
  const walk = (directory) => {
    for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
      const fullPath = path.join(directory, entry.name)
      if (entry.isDirectory()) {
        walk(fullPath)
        continue
      }
      if (!/\.(?:css|scss)$/.test(entry.name)) continue

      const content = fs.readFileSync(fullPath, 'utf8')
      failures.push(...findWebRadiusScaleViolations(content, rel(fullPath)))
    }
  }

  walk(scanRoot)
  if (failures.length) {
    throw new Error(
      `Web radius scale violations detected:\n${failures.join('\n')}`,
    )
  }
}

const lint = () => {
  const source = readSource()
  lintRegisteredAliases(source)
  lintGeneratedHeaders()
  lintTokenFixtures()
  lintOutputSnapshots()
  lintAvaloniaTypeSnapshots(source)
  lintStableComponentHardcoding()
  lintWebRadiusUsage()
  console.log('Token source and generated artifact metadata are valid.')
}

const isDirectExecution =
  process.argv[1] !== undefined &&
  path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)

if (isDirectExecution) {
  const command = process.argv[2]

  try {
    if (command === 'generate') {
      writeFiles(renderAll())
    } else if (command === 'check') {
      checkFiles(renderAll())
    } else if (command === 'lint') {
      lint()
    } else {
      throw new Error(
        'Usage: node scripts/token-pipeline.mjs <generate|check|lint>',
      )
    }
  } catch (error) {
    console.error(error instanceof Error ? error.message : error)
    process.exitCode = 1
  }
}
